"use strict";

// OpenClaw Hook：group-activity-memory
// 用途：教練 2026-08-24 交辦——「活動記錄群」是長時間討論用的群組（收集攤販/廠商資訊、
//       活動idea等），教練習慣討論一段時間後說「幫我彙整」。問題是：群組即時對話的
//       agent session 不保證能撐過一整場長討論（context 太長會被壓縮/重啟，
//       跟教練個人對話同樣的風險，見 hooks/inbound-message-echo-log 的起因）。
//       如果彙整當下只看得到「最近幾則」，彙整出來的東西就會漏掉討論前段，教練白討論了。
//
// 做法（兩個獨立動作，同一支 hook）：
//   ① 每一則訊息進來就同步寫進這個群專屬的記憶檔（純文字/追加寫入，不靠 agent 記得）
//   ② 偵測到「彙整/整理/統整/總結/摘要」這類字眼 → 把整份記憶檔內容注入到這一輪的
//      context 裡，讓 agent 真的看得到完整討論史，不是只靠自己殘存的對話記憶。
//
// 事件：message:preprocessed（agent 開始處理前，跟 invoice-inbound/inbound-message-echo-log
// 同一個事件，寫入時機一致，agent 掛掉也不影響落地）。
// 軍師建立 2026-08-24。

const fs = require('fs');
const path = require('path');

const HOME = process.env.HOME;
const MEMORY_DIR = path.join(HOME, '.openclaw', 'workspace', 'group_memory');
const DEBUG_LOG = path.join(HOME, '.openclaw', 'logs', 'group-activity-memory-debug.log');

// 要追蹤的群組清單。之後教練要幫其他群組也做這個功能，在這裡加一行即可
// （chat_id 查法：看 state/inbound_echo/*.jsonl 裡該群訊息的 "id:-xxxx" 或
// gateway.log 的 "Inbound message telegram:group:-xxxx"）。
const TRACKED_GROUPS = {
  // 2026-08-24教練把群組從「活動記錄群」改名為「活動討論群」（教練口頭原始說法），
  // chat_id不變，這裡的 name/file 用教練現在實際稱呼的名字。
  "-1003537129853": { name: "活動討論群", file: "活動討論群.md" },
};

// 命中任一就視為「請幫我整理」，把整份記憶檔灌回 context
const SUMMARY_TRIGGER_RE = /彙整|汇整|整理一下|幫我整理|統整|统整|做?個?總結|做?個?总结|摘要|summar/i;

// 超過這個字數才會截斷注入（避免單次注入爆掉 context），main agent 有檔案讀取權限，
// 截斷時會附上完整路徑，真的需要更早的內容可以自己讀檔案。
const MAX_INJECT_CHARS = 30000;

function debugLog(msg) {
  try {
    fs.mkdirSync(path.dirname(DEBUG_LOG), { recursive: true });
    fs.appendFileSync(DEBUG_LOG, new Date().toISOString() + ' ' + msg + '\n');
  } catch (e) {}
}

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    c.body, c.bodyForAgent,
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

// 群組訊息的 body 前面通常帶 "[Telegram 活動記錄群 id:-xxx +1m Mon ... coach (123): 內容]"
// 這種格式（inbound-message-echo-log 也是靠這個格式取得群名/寄件人），這裡把「寄件人：內容」
// 拆出來，記憶檔只留人話，不留系統包裝的雜訊。
function parseSenderAndBody(rawText) {
  const m = rawText.match(/\]?\s*([^\[\]:]{1,30})\s*\(([^()]+)\)\s*:\s*([\s\S]*)$/);
  if (m) {
    return { sender: m[1].trim(), body: m[3].trim() };
  }
  return { sender: '未知', body: rawText.trim() };
}

function resolveChatId(event) {
  const ctx = (event && event.context) || {};
  const raw = String(
    ctx.senderId || ctx.conversationId || ctx.from || ctx.to ||
    event.from || event.senderId || ''
  );
  return raw.replace(/^(telegram|line|whatsapp|discord|sms):/i, '');
}

function taipeiStamp() {
  const d = new Date(Date.now() + 8 * 3600 * 1000);
  return d.toISOString().replace('T', ' ').slice(0, 16);
}

function appendToMemory(filePath, sender, body) {
  const entry = `### ${taipeiStamp()}｜${sender}\n${body}\n\n`;
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.appendFileSync(filePath, entry);
}

function readMemoryForInjection(filePath) {
  let content;
  try {
    content = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    return null;
  }
  if (!content.trim()) return null;
  if (content.length <= MAX_INJECT_CHARS) return { content, truncated: false };
  return { content: content.slice(-MAX_INJECT_CHARS), truncated: true };
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;

  try {
    const chatId = resolveChatId(event);
    // 群組聊天的 senderId 格式是 "telegram:group:-xxx"，前面 replace 只拔掉頻道前綴，
    // 這裡再把 "group:" 拔掉才會對到 TRACKED_GROUPS 的 key
    const groupId = chatId.replace(/^group:/, '');
    const tracked = TRACKED_GROUPS[groupId];
    if (!tracked) return; // 不是要追蹤的群組，什麼都不做

    const rawText = extractText(event);
    if (!rawText) return;

    const { sender, body } = parseSenderAndBody(rawText);
    if (!body) return;

    const filePath = path.join(MEMORY_DIR, tracked.file);
    appendToMemory(filePath, sender, body);

    if (SUMMARY_TRIGGER_RE.test(body)) {
      const mem = readMemoryForInjection(filePath);
      if (mem) {
        const ctx = event.context;
        if (!ctx.inject) ctx.inject = [];
        if (Array.isArray(ctx.inject)) {
          const header = mem.truncated
            ? `📋「${tracked.name}」完整討論記憶（因篇幅過長只顯示最近 ${MAX_INJECT_CHARS} 字，需要更早的內容可讀取 ${filePath}）：`
            : `📋「${tracked.name}」完整討論記憶（教練請你彙整，這是這個群組從頭到現在的完整記錄，不是只有你剛才看到的那幾則）：`;
          ctx.inject.push({ role: 'system', content: header + '\n\n' + mem.content });
        }
      }
    }
  } catch (err) {
    debugLog('ERROR ' + (err && err.message));
  }
};

module.exports = handler;
module.exports.default = handler;

