"use strict";

// OpenClaw Hook：session-summary-trigger
// 用途：教練對小龍蝦(main agent)說「總結」時，比照桌面版「總結」暗號——
//   立即蒸餾存檔本場對話 + 標記待清空session + 直接回覆教練，不依賴模型配合
//   （message:preprocessed 的 inject 是 fire-and-forget，見
//   feedback_openclaw_hook_fire_and_forget.md）。
// 事件：message:preprocessed。
// 軍師建立 2026-08-25（教練交辦Q1，方案沿用v130接力棒定案）。詳見 HOOK.md。

const fs = require('fs');
const path = require('path');
const https = require('https');
const { execFile } = require('child_process');

const HOME = process.env.HOME;
const SYNC_SCRIPT = path.join(HOME, '.openclaw', 'scripts', 'sync-telegram-memory.sh');
const PENDING_MARKER = '/tmp/.pending_session_summary_main';
const DEBUG_LOG = path.join(HOME, '.openclaw', 'logs', 'session-summary-trigger-debug.log');
const OPENCLAW_CONFIG_PATH = path.join(HOME, '.openclaw', 'openclaw.json');
const COACH_TELEGRAM_CHAT_ID = '6124913915';
const COACH_LINE_IDS = ['U895a0ad8e49d75f8303dc3d067282dc0', 'U168903487f0ba2b666ddc62b854de351'];

// 觸發詞：整句主要是「總結」類指令才觸發，避免「幫我寫一份年度總結報告」誤觸發
// （比照桌面版 scripts/summary_upload_trigger.sh 的判斷邏輯）
const TRIGGER_RE = /^總結[\s。！!，,]*$|^總結[，,]|總結上傳|總結一下/;

function debugLog(msg) {
  try {
    fs.mkdirSync(path.dirname(DEBUG_LOG), { recursive: true });
    fs.appendFileSync(DEBUG_LOG, new Date().toISOString() + ' ' + msg + '\n');
  } catch (e) {}
}

// 沿用 rule-reminder/handler.js 已驗證過的三層 fallback（bot-relay-inbound v2.5 同款）
function resolveAgentId(event) {
  const ctx = (event && event.context) ? event.context : {};
  const raw =
    event.agentId || ctx.agentId ||
    (ctx.agent && ctx.agent.id) || ctx.agent || '';
  if (raw) return String(raw).toLowerCase();
  const sessionKey = event.sessionKey || ctx.sessionKey || '';
  if (sessionKey) {
    const parts = String(sessionKey).split(':');
    if (parts[0] === 'agent' && parts[1]) return parts[1].toLowerCase();
  }
  return 'unknown';
}

// 沿用 group-activity-memory / inbound-message-echo-log 已驗證過的 senderId 抽取
function resolveSenderRaw(event) {
  const ctx = (event && event.context) || {};
  return String(
    ctx.senderId || ctx.conversationId || ctx.from || ctx.to ||
    event.from || event.senderId || ''
  );
}

function isCoach(senderRaw) {
  if (!senderRaw) return false;
  if (senderRaw.includes(COACH_TELEGRAM_CHAT_ID)) return true;
  return COACH_LINE_IDS.some((id) => senderRaw.includes(id));
}

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    c.body, c.bodyForAgent,
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

// 沿用 context-overflow-guard/handler.js 已驗證過的直發模式：不靠 inject，
// 這是「鎖」——不管模型有沒有處理這則訊息，教練一定會收到這則確認。
function sendTelegramDirect(text) {
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, 'utf-8'));
    const botToken = cfg && cfg.channels && cfg.channels.telegram &&
      cfg.channels.telegram.accounts && cfg.channels.telegram.accounts.bot_main &&
      cfg.channels.telegram.accounts.bot_main.botToken;
    if (!botToken) { debugLog('讀不到 bot_main botToken'); return; }

    const payload = JSON.stringify({ chat_id: COACH_TELEGRAM_CHAT_ID, text: text });
    const req = https.request({
      hostname: 'api.telegram.org',
      path: '/bot' + botToken + '/sendMessage',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
      timeout: 8000,
    }, (res) => { res.on('data', () => {}); });
    req.on('error', (e) => debugLog('sendTelegramDirect req error: ' + e.message));
    req.on('timeout', () => req.destroy());
    req.write(payload);
    req.end();
  } catch (e) {
    debugLog('sendTelegramDirect error: ' + (e && e.message));
  }
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;

  try {
    const agentId = resolveAgentId(event);
    // 目前只服務小龍蝦(main)，peipei記憶架構不同，需另外評估，見 HOOK.md
    if (agentId !== 'main') return;

    const senderRaw = resolveSenderRaw(event);
    if (!isCoach(senderRaw)) return; // 只信任教練本人，避免任何人一句話清空全部session

    const text = extractText(event);
    if (!text) return;
    if (!TRIGGER_RE.test(text.trim())) return;

    debugLog('觸發「總結」 sender=' + senderRaw + ' text=' + text.slice(0, 60));

    // ① 立即蒸餾存檔（純文字解析，不燒AI token，不觸碰session狀態，安全）
    execFile('bash', [SYNC_SCRIPT, '--force'], { timeout: 30000 }, (err) => {
      if (err) debugLog('sync-telegram-memory.sh --force 失敗: ' + err.message);
      else debugLog('sync-telegram-memory.sh --force 完成');
    });

    // ② 寫待清除標記，交給 auto-fix-session-lock.sh 從外部安全清空+重啟
    //    （不在這支hook裡自己重啟自己所在的gateway process）
    try {
      fs.writeFileSync(PENDING_MARKER, String(Date.now()));
    } catch (e) {
      debugLog('寫標記檔失敗: ' + (e && e.message));
    }

    // ③ 立即回覆教練，不等清空真正完成
    sendTelegramDirect('🦞 收到「總結」，正在幫您整理存檔，稍後（最多2分鐘內）會清空對話讓您重新開始，請稍候。');
  } catch (err) {
    debugLog('ERROR ' + (err && err.message));
  }
};

module.exports = handler;
module.exports.default = handler;

