"use strict";
// 測試 hooks/session-summary-trigger/handler.js 的觸發邏輯
// 用假的 event 物件跑過 handler，不碰真實 session/gateway。
// execFile 呼叫 sync-telegram-memory.sh 屬於外部行為，測試時允許實際跑一次
// （該腳本本身是唯讀解析+append memory檔，無破壞性）。

const fs = require('fs');
const path = require('path');
const os = require('os');

const HANDLER_PATH = path.join(process.env.HOME, '.openclaw', 'hooks', 'session-summary-trigger', 'handler.js');
const MARKER = '/tmp/.pending_session_summary_main';
const DEBUG_LOG = path.join(process.env.HOME, '.openclaw', 'logs', 'session-summary-trigger-debug.log');

function mkEvent({ agentId = 'main', senderId = 'telegram:direct:6124913915', text = '總結' } = {}) {
  return {
    type: 'message',
    action: 'preprocessed',
    context: {
      agentId,
      senderId,
      body: text,
      inject: [],
    },
  };
}

async function run() {
  const handler = require(HANDLER_PATH);
  let pass = 0, fail = 0;

  function cleanMarker() {
    try { fs.unlinkSync(MARKER); } catch (e) {}
  }

  async function expectTrigger(name, evt, shouldTrigger) {
    cleanMarker();
    await handler(evt);
    // 給 execFile/fs.writeFileSync 一點時間（writeFileSync是同步的，這裡主要等debug log flush）
    await new Promise((r) => setTimeout(r, 300));
    const markerExists = fs.existsSync(MARKER);
    const ok = markerExists === shouldTrigger;
    console.log((ok ? '✅' : '❌'), name, '| marker exists=', markerExists, '| expected=', shouldTrigger);
    ok ? pass++ : fail++;
    cleanMarker();
  }

  console.log('=== 正向案例：教練說「總結」應該觸發 ===');
  await expectTrigger('教練Telegram純「總結」', mkEvent({ text: '總結' }), true);
  await expectTrigger('教練Telegram「總結。」', mkEvent({ text: '總結。' }), true);
  await expectTrigger('教練Telegram「總結一下」', mkEvent({ text: '總結一下' }), true);
  await expectTrigger('教練Telegram「總結上傳」', mkEvent({ text: '總結上傳' }), true);
  await expectTrigger('教練Telegram「總結，謝謝」', mkEvent({ text: '總結，今天先這樣' }), true);
  await expectTrigger('教練LINE(第一身份)說總結', mkEvent({ senderId: 'line:direct:U895a0ad8e49d75f8303dc3d067282dc0', text: '總結' }), true);
  await expectTrigger('教練LINE(第二身份)說總結', mkEvent({ senderId: 'line:direct:U168903487f0ba2b666ddc62b854de351', text: '總結' }), true);

  console.log('=== 反向案例：不該觸發 ===');
  await expectTrigger('長句子提到總結不該誤觸發', mkEvent({ text: '幫我寫一份年度總結報告' }), false);
  await expectTrigger('非教練發送者不該觸發', mkEvent({ senderId: 'telegram:direct:9999999999', text: '總結' }), false);
  await expectTrigger('非main agent(peipei)不該觸發', mkEvent({ agentId: 'peipei', text: '總結' }), false);
  await expectTrigger('非message事件不該觸發', { type: 'other', action: 'preprocessed', context: {} }, false);
  await expectTrigger('空文字不該觸發', mkEvent({ text: '' }), false);
  await expectTrigger('普通聊天不該觸發', mkEvent({ text: '今天天氣如何' }), false);

  console.log('\n' + (fail === 0 ? '🎉 全部通過' : '⚠️ 有失敗') + ` (${pass} pass / ${fail} fail)`);
  process.exit(fail === 0 ? 0 : 1);
}

run();

