function typeDigit(el, ch) {
  const code = ch.charCodeAt(0);
  const opts = {key: ch, code: 'Digit'+ch, keyCode: code, which: code, charCode: code, bubbles: true, cancelable: true};
  el.dispatchEvent(new KeyboardEvent('keydown', opts));
  const kp = new KeyboardEvent('keypress', opts);
  const notCancelled = el.dispatchEvent(kp);
  el.value = el.value + ch;
  el.dispatchEvent(new Event('input', {bubbles:true}));
  el.dispatchEvent(new KeyboardEvent('keyup', opts));
  return { notCancelled };
}
const el = document.getElementById('ItemCount1');
el.focus();
el.value = '';
const r = typeDigit(el, '1');
({ result: r, valueAfter: el.value })

